import type { FilterExpression } from '@wix/sdk-types'
import type { WixDataItem, WixDataQuerySpec } from './types'
import type { WixDataBulkPatchOptions } from './WixDataPatch'

/**
 * Options builder for bulk patch operations.
 *
 * Use this builder to configure bulk patch behavior such as hooks suppression,
 * and conditional patching.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataBulkPatchOptionsBuilder {
  /**
   * Sets whether to suppress bulk patch hooks.
   *
   * When `true`, the bulk patch runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataBulkPatchOptionsBuilder
  /**
   * Sets whether to include draft items when patching items in bulk.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataBulkPatchOptionsBuilder
  /**
   * Sets the condition that determines which items to patch.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkPatchOptionsBuilder
  /**
   * Builds the bulk patch options object.
   */
  build(): WixDataBulkPatchOptions
}

class WixDataBulkPatchOptionsBuilderImpl
  implements WixDataBulkPatchOptionsBuilder
{
  constructor(private readonly options: WixDataBulkPatchOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataBulkPatchOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataBulkPatchOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkPatchOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataBulkPatchOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataBulkPatchOptions
  ): WixDataBulkPatchOptionsBuilder {
    return new WixDataBulkPatchOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new bulk patch options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a bulk patch options builder"
 * import { items, BulkPatchOptionsBuilder, Filter } from '@wix/data'
 *
 * const options = BulkPatchOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const result = await items.bulkPatch('myCollection', ['item-1', 'item-2'], [], options)
 * ```
 */
export const BulkPatchOptionsBuilder: () => WixDataBulkPatchOptionsBuilder =
  () => new WixDataBulkPatchOptionsBuilderImpl()
